function Empty({ text = 'Nothing here yet.' }: { text?: string }) { return <div className="rounded-sm border border-dashed border-border px-6 py-16 text-center"><Sparkles className="mx-auto mb-3 text-[#d69b45]" size={22} /><p className="display-font text-2xl">{text}</p></div>; }
