function EventCard({ event, index = 0 }: { event: any; index?: number }) {
  const parts = dateParts(event.date);
  return <Link href={`/events/${event.slug}`} className="group block" data-testid={`card-event-${event.id}`}><div className="relative aspect-[4/5] overflow-hidden bg-[#d9c4ae]"><img src={img(event.poster, index)} alt={event.title} className="h-full w-full object-cover transition duration-700 group-hover:scale-105" /><div className="poster-gradient absolute inset-0" /><div className="absolute left-4 top-4 flex h-14 w-14 flex-col items-center justify-center bg-[#f3e9dc] text-[#4b231b]"><span className="mono-font text-[9px] font-bold tracking-wider">{parts.month}</span><span className="text-2xl font-bold leading-none">{parts.day}</span></div><div className="absolute bottom-5 left-5 right-5"><p className="mono-font text-[9px] uppercase tracking-[.19em] text-[#e5ae55]">{event.city} · {event.startTime}</p><h3 className="mt-2 text-2xl font-bold leading-tight text-[#f7eddf]">{event.title}</h3><p className="mt-1 text-xs text-[#e6d5c8]">{event.venue}</p></div></div></Link>;
}

function Events() {
  const [country, setCountry] = useState<Country>(Country.CA);
  const [city, setCity] = useState('All cities');
  const events = useListPublicEvents({ status: EventStatus.UPCOMING, country });
  const past = useListPublicEvents({ status: EventStatus.PAST, country });
  const list = (events.data || []).filter((e) => city === 'All cities' || e.city === city);
  const cities = [...new Set((events.data || []).map((e) => e.city))];
  const switchCountry = (next: Country) => { setCountry(next); setCity('All cities'); };
  return <div className="jannat-grain min-h-screen bg-[#f3e9dc] text-[#4b231b]">
    <PublicHeader />
    <div className="fixed right-5 top-24 z-40"><CountryToggle country={country} setCountry={switchCountry} /></div>
    <section className="bg-[#351a16] px-5 pb-16 pt-36 text-[#f7eddf] lg:px-10"><div className="mx-auto max-w-7xl"><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#e5ae55]">{country === Country.CA ? 'Canada' : 'USA'} calendar</p><h1 className="display-font mt-5 max-w-3xl text-6xl leading-[.9] md:text-8xl">Find your<br /><i>next night.</i></h1><p className="mt-7 max-w-lg text-sm leading-7 text-[#d8c5b5]">From intimate rooms to full-scale celebrations, this is where the next unforgettable evening starts.</p></div></section>
    <main className="mx-auto max-w-7xl px-5 py-14 lg:px-10 lg:py-20">
      <div className="mb-10 flex flex-wrap items-center justify-between gap-4 border-b border-[#d5c2b0] pb-5"><h2 className="display-font text-3xl md:text-4xl">Upcoming events</h2><div className="relative"><select value={city} onChange={(e) => setCity(e.target.value)} className="focus-ring appearance-none rounded-full border border-[#c9b4a1] bg-transparent py-2.5 pl-4 pr-10 text-xs font-bold" data-testid="select-city"><option>All cities</option>{cities.map((c) => <option key={c}>{c}</option>)}</select><ChevronDown size={14} className="pointer-events-none absolute right-3 top-3.5" /></div></div>
      {events.isLoading ? <Loading /> : events.isError ? <ErrorState retry={() => events.refetch()} /> : list.length ? <div className="grid gap-x-6 gap-y-12 md:grid-cols-3">{list.map((e, i) => <EventCard event={e} index={i} key={e.id} />)}</div> : <Empty text={`No upcoming events in ${country === Country.CA ? 'Canada' : 'the USA'} yet.`} />}
      <div className="mt-28 border-t border-[#d5c2b0] pt-10"><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#a45c3c]">The afterglow</p><h2 className="display-font mt-3 text-4xl">Past events</h2>{past.isLoading ? <Loading /> : (past.data?.length || 0) > 0 ? <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">{past.data?.slice(0, 8).map((e, i) => <EventCard event={e} index={i + 1} key={e.id} />)}</div> : <p className="mt-5 text-sm text-muted-foreground">The archive is just getting started.</p>}</div>
    </main><PublicFooter />
  </div>;
}

function EventDetail() {
  const { slug = '' } = useParams<{ slug: string }>();
  const q = useGetPublicEvent(slug);
  if (q.isLoading) return <><PublicHeader /><Loading /><PublicFooter /></>;
  if (q.isError || !q.data) return <><PublicHeader /><ErrorState retry={() => q.refetch()} /><PublicFooter /></>;
  const event = q.data;
  const share = async () => { const data = { title: event.title, text: `${event.title} | ${dateLabel(event.date)}`, url: window.location.href }; if (navigator.share) await navigator.share(data); else await navigator.clipboard.writeText(window.location.href); };
  return <div className="jannat-grain bg-[#24120f] text-[#f7eddf]"><PublicHeader /><section className="relative min-h-[75svh] overflow-hidden"><img src={img(event.poster)} alt={event.title} className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(36,18,15,.95),rgba(36,18,15,.25))]" /><div className="relative mx-auto flex min-h-[75svh] max-w-7xl items-end px-5 pb-14 pt-36 lg:px-10 lg:pb-24"><div className="max-w-3xl"><Link href="/events" className="mb-10 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.2em] text-[#e5ae55]" data-testid="link-back-events"><ArrowLeft size={14} /> All events</Link><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#e5ae55]">{dateLabel(event.date)} · {event.city}</p><h1 className="display-font mt-5 text-6xl leading-[.88] md:text-9xl">{event.title}</h1><div className="mt-8 flex flex-wrap gap-5 text-xs text-[#e6d5c8]"><span className="inline-flex items-center gap-2"><MapPin size={14} className="text-[#e5ae55]" />{event.venue}</span><span className="inline-flex items-center gap-2"><CalendarDays size={14} className="text-[#e5ae55]" />Doors {event.startTime}</span></div></div></div></section><section className="bg-[#f3e9dc] px-5 py-16 text-[#4b231b] lg:px-10 lg:py-24"><div className="mx-auto grid max-w-7xl gap-12 md:grid-cols-[1.4fr_.8fr]"><div><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#a45c3c]">The details</p><div className="prose mt-6 max-w-2xl text-[#634c42]" dangerouslySetInnerHTML={{ __html: event.description || '<p>Come as you are. Stay for the chorus.</p>' }} /><div className="mt-10 flex flex-wrap gap-3">{event.ageRestriction && <span className="rounded-full border border-[#c9b4a1] px-4 py-2 text-xs">{event.ageRestriction}</span>}{event.dressCode && <span className="rounded-full border border-[#c9b4a1] px-4 py-2 text-xs">{event.dressCode}</span>}</div></div><aside className="h-fit border-t-2 border-[#4b231b] pt-5"><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[#a45c3c]">Venue</p><h2 className="mt-3 text-xl font-bold">{event.venue}</h2><p className="mt-1 text-sm text-[#765f54]">{event.address}, {event.city}, {event.province}</p>{event.ticketUrl && <a href={event.ticketUrl} target="_blank" rel="noreferrer" className="mt-7 flex items-center justify-between rounded-full bg-[#4b231b] px-5 py-3.5 text-xs font-bold uppercase tracking-[.16em] text-[#f3e9dc]" data-testid="link-buy-tickets">Get tickets <Ticket size={16} /></a>}{event.instagramUrl && <a href={event.instagramUrl} target="_blank" rel="noreferrer" className="mt-3 flex items-center justify-between rounded-full border border-[#c9b4a1] px-5 py-3.5 text-xs font-bold uppercase tracking-[.16em]" data-testid="link-event-instagram">Event updates <Instagram size={16} /></a>}<button onClick={share} className="mt-3 flex w-full items-center justify-between rounded-full border border-[#c9b4a1] px-5 py-3.5 text-xs font-bold uppercase tracking-[.16em]" data-testid="button-share-event">Share this night <LinkIcon size={16} /></button></aside></div></section><PublicFooter /></div>;
}

function Albums() {
  const q = useListPublicAlbums();
  return <div className="jannat-grain min-h-screen bg-[#f3e9dc] text-[#4b231b]"><PublicHeader /><section className="bg-[#351a16] px-5 pb-16 pt-36 text-[#f7eddf] lg:px-10"><div className="mx-auto max-w-7xl"><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#e5ae55]">The archive</p><h1 className="display-font mt-5 max-w-4xl text-6xl leading-[.9] md:text-8xl">Good nights<br /><i>leave evidence.</i></h1></div></section><main className="mx-auto max-w-7xl px-5 py-14 lg:px-10 lg:py-20">{q.isLoading ? <Loading /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : q.data?.length ? <div className="columns-1 gap-6 sm:columns-2 lg:columns-3">{q.data.map((a, i) => <Link href={`/albums/${a.slug}`} key={a.id} className="group mb-6 block break-inside-avoid" data-testid={`card-album-${a.id}`}><div className="relative overflow-hidden bg-[#d9c4ae]"><img src={img(a.coverImage, i + 1)} alt={a.title} className="block max-h-[550px] min-h-[260px] w-full object-cover transition duration-700 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-[#24120f]/85 via-transparent to-transparent" /><div className="absolute bottom-5 left-5 text-[#f7eddf]"><p className="mono-font text-[9px] uppercase tracking-[.18em] text-[#e5ae55]">{a.city || 'Canada'} · {dateLabel(a.date)}</p><h2 className="mt-1 text-2xl font-bold">{a.title}</h2></div></div></Link>)}</div> : <Empty text="The first chapter is coming." />}</main><PublicFooter /></div>;
}

function AlbumDetail() {
  const { slug = '' } = useParams<{ slug: string }>();
  const q = useGetPublicAlbum(slug);
  const [lightbox, setLightbox] = useState<number | null>(null);
  if (q.isLoading) return <><PublicHeader /><Loading /><PublicFooter /></>;
  if (q.isError || !q.data) return <><PublicHeader /><ErrorState retry={() => q.refetch()} /><PublicFooter /></>;
  const album = q.data; const media = album.media || [];
  return <div className="jannat-grain min-h-screen bg-[#24120f] text-[#f7eddf]"><PublicHeader /><section className="mx-auto max-w-7xl px-5 pb-12 pt-36 lg:px-10"><Link href="/albums" className="inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.2em] text-[#e5ae55]" data-testid="link-back-albums"><ArrowLeft size={14} /> All albums</Link><h1 className="display-font mt-8 text-6xl md:text-8xl">{album.title}</h1><p className="mt-5 max-w-xl text-sm leading-7 text-[#d8c5b5]">{album.description}</p></section><main className="mx-auto max-w-7xl columns-2 gap-3 px-5 pb-24 sm:columns-3 lg:px-10">{media.length ? media.map((m, i) => <button key={m.id} onClick={() => setLightbox(i)} className="group relative mb-3 block w-full overflow-hidden text-left" data-testid={`button-media-${m.id}`}><img src={img(m.thumbnail || m.url, i)} alt={m.altText} className="w-full object-cover transition duration-700 group-hover:scale-105" /><span className="absolute right-3 top-3 rounded-full bg-[#24120f]/70 p-2 opacity-0 transition group-hover:opacity-100">{m.type === MediaType.VIDEO ? <Video size={13} /> : <ImagePlus size={13} />}</span></button>) : <div className="col-span-full"><Empty text="Photos are on their way." /></div>}</main>{lightbox !== null && <div className="fixed inset-0 z-50 grid place-items-center bg-[#170b09]/95 p-5" onClick={() => setLightbox(null)}><button onClick={() => setLightbox(null)} className="absolute right-5 top-5 rounded-full border border-white/20 p-2" data-testid="button-close-lightbox"><X /></button>{media[lightbox]?.type === MediaType.VIDEO ? <video src={media[lightbox]?.url} controls autoPlay onClick={(e) => e.stopPropagation()} className="max-h-[88vh] max-w-full" /> : <img src={img(media[lightbox]?.url, lightbox)} alt={media[lightbox]?.altText || album.title} className="max-h-[88vh] max-w-full object-contain" />}</div>}<PublicFooter /></div>;
}

function About() {
  return <div className="jannat-grain min-h-screen bg-[#f3e9dc] text-[#4b231b]"><PublicHeader /><section className="bg-[#351a16] px-5 pb-20 pt-36 text-[#f7eddf] lg:px-10 lg:pb-28"><div className="mx-auto max-w-7xl"><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#e5ae55]">Our story</p><h1 className="display-font mt-5 max-w-4xl text-6xl leading-[.9] md:text-9xl">A little bit<br />of everywhere.</h1></div></section><main><section className="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-2 lg:px-10 lg:py-28"><div><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#a45c3c]">Why Jannat exists</p><h2 className="display-font mt-4 text-5xl leading-[.95] md:text-7xl">The soundtrack<br />to belonging.</h2></div><div className="space-y-5 text-base leading-8 text-[#6d564b]"><p>Jannat is a love letter to the South Asian community across Canada, a place where the classics still hit, new sounds find their people, and a dance floor can feel like home.</p><p>We make nights that move between generations. The old chorus, the new beat, the friend you came with, and the stranger you leave knowing. That is the magic we are here for.</p><p>Every city has its own rhythm. We are here to turn it up.</p></div></section><section className="grid min-h-[55vh] grid-cols-2 bg-[#d69b45] text-[#4b231b]"><div className="col-span-2 min-h-[30vh] bg-cover bg-center md:col-span-1 md:min-h-full" style={{ backgroundImage: `url(${demoImages[2]})` }} /><div className="col-span-2 flex items-end p-8 md:col-span-1 md:p-14"><div><p className="mono-font text-[10px] uppercase tracking-[.25em]">Across Canada</p><p className="display-font mt-5 text-5xl leading-[.9] md:text-7xl">Many cities.<br />One feeling.</p><p className="mt-8 max-w-sm text-sm leading-7">Toronto, Vancouver, Montréal, Calgary, and the places still to come.</p></div></div></section></main><PublicFooter /></div>;
}

function Contact() {
  const submit = useSubmitContact();
  const [sent, setSent] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', phone: '', subject: '', inquiryType: ContactInputInquiryType.General, message: '' });
  const update = (key: string, value: string) => setForm((f) => ({ ...f, [key]: value }));
  const send = (e: React.FormEvent) => { e.preventDefault(); submit.mutate({ data: { ...form, phone: form.phone || null } }, { onSuccess: () => setSent(true) }); };
  return <div className="jannat-grain min-h-screen bg-[#f3e9dc] text-[#4b231b]"><PublicHeader /><section className="bg-[#351a16] px-5 pb-16 pt-36 text-[#f7eddf] lg:px-10"><div className="mx-auto max-w-7xl"><p className="mono-font text-[10px] uppercase tracking-[.25em] text-[#e5ae55]">Say hello</p><h1 className="display-font mt-5 text-6xl leading-[.9] md:text-8xl">Let’s make<br /><i>something happen.</i></h1></div></section><main className="mx-auto grid max-w-7xl gap-14 px-5 py-16 lg:grid-cols-[.7fr_1.3fr] lg:px-10 lg:py-24"><div><p className="max-w-sm text-sm leading-7 text-[#6d564b]">Have a question, a big idea, or a room that deserves a soundtrack? We would love to hear from you.</p><div className="mt-10 border-t border-[#c9b4a1] pt-5"><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[#a45c3c]">Email</p><a href="mailto:contactthejannat@gmail.com" className="mt-2 block break-all text-xl font-bold" data-testid="link-contact-email">contactthejannat@gmail.com</a></div></div>{sent ? <div className="flex min-h-[360px] flex-col justify-center border-t-2 border-[#4b231b]"><Check className="mb-5 text-[#a45c3c]" size={30} /><h2 className="display-font text-5xl">Message received.</h2><p className="mt-3 max-w-md text-sm leading-7 text-[#6d564b]">We’ll be in touch soon. In the meantime, keep an eye on the calendar.</p><Link href="/events" className="mt-7 inline-flex w-fit rounded-full bg-[#4b231b] px-5 py-3 text-xs font-bold uppercase tracking-wider text-[#f3e9dc]" data-testid="link-contact-events">See upcoming events</Link></div> : <form onSubmit={send} className="grid gap-5 border-t-2 border-[#4b231b] pt-7 sm:grid-cols-2"><Field label="Your name" value={form.name} onChange={(v) => update('name', v)} required testId="input-contact-name" /><Field label="Email address" type="email" value={form.email} onChange={(v) => update('email', v)} required testId="input-contact-email" /><Field label="Phone (optional)" value={form.phone} onChange={(v) => update('phone', v)} testId="input-contact-phone" /><label className="grid gap-2 text-xs font-bold"><span>What can we help with?</span><select value={form.inquiryType} onChange={(e) => update('inquiryType', e.target.value)} className="focus-ring h-11 border-b border-[#bda894] bg-transparent text-sm outline-none" data-testid="select-inquiry-type">{Object.values(ContactInputInquiryType).map((v) => <option key={v}>{v}</option>)}</select></label><Field label="Subject" value={form.subject} onChange={(v) => update('subject', v)} required testId="input-contact-subject" /><label className="grid gap-2 text-xs font-bold sm:col-span-2"><span>Tell us more</span><textarea required rows={5} value={form.message} onChange={(e) => update('message', e.target.value)} className="focus-ring resize-none border-b border-[#bda894] bg-transparent py-2 text-sm outline-none" data-testid="textarea-contact-message" /></label><button disabled={submit.isPending} className="inline-flex w-fit items-center gap-3 rounded-full bg-[#4b231b] px-6 py-3.5 text-xs font-bold uppercase tracking-[.16em] text-[#f3e9dc] disabled:opacity-60" data-testid="button-submit-contact">{submit.isPending ? <Loader2 className="animate-spin" size={15} /> : <Mail size={15} />} Send inquiry</button>{submit.isError && <p className="text-sm text-[#a14432] sm:col-span-2">Something went wrong. Please try again.</p>}</form>}</main><PublicFooter /></div>;
}

function Field({ label, value, onChange, type = 'text', required = false, testId }: { label: string; value: string; onChange: (v: string) => void; type?: string; required?: boolean; testId: string }) { return <label className="grid gap-2 text-xs font-bold"><span>{label}</span><input required={required} type={type} value={value} onChange={(e) => onChange(e.target.value)} className="focus-ring h-11 border-b border-[#bda894] bg-transparent text-sm outline-none" data-testid={testId} /></label>; }

const adminLinks = [['Overview', '/admin', LayoutDashboard], ['Events', '/admin/events', CalendarDays], ['Albums', '/admin/albums', ImagePlus], ['Media library', '/admin/media', UploadCloud], ['Homepage', '/admin/homepage', Sparkles], ['Messages', '/admin/messages', MessageCircle], ['Settings', '/admin/settings', Settings]] as const;
function UploadProgressToast() {
  const [state, setState] = useState({ active: false, progress: 0, name: '' });
  useEffect(() => { const listener = (event: Event) => setState((event as CustomEvent).detail); window.addEventListener('jannat-upload-progress', listener); return () => window.removeEventListener('jannat-upload-progress', listener); }, []);
  if (!state.active) return null;
  return <div className="fixed bottom-5 right-5 z-[100] w-[min(360px,calc(100vw-2.5rem))] border border-[#8a682d] bg-[#070604] p-5 text-[#f7e8c2] shadow-2xl" role="status" aria-live="polite"><div className="flex items-center justify-between gap-4"><span className="truncate text-xs font-bold">{state.name}</span><span className="mono-font text-xs text-[#d7a84f]">{state.progress}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#d7a84f] transition-[width] duration-150" style={{ width: `${state.progress}%` }} /></div><p className="mt-2 text-[10px] uppercase tracking-[.15em] text-[#cbb1a0]">{state.progress < 100 ? 'Uploading file' : 'Upload complete'}</p></div>;
}
function AdminShell({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false); const [location] = useLocation();
  return <div className="admin-shell min-h-[100dvh] text-[#34241f]"><aside className={`fixed inset-y-0 left-0 z-40 w-64 bg-[#2b1916] px-5 py-7 text-[#f4e7d8] transition-transform md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between"><Logo light /><button onClick={() => setOpen(false)} className="md:hidden" data-testid="button-close-sidebar"><X size={18} /></button></div><p className="mono-font mb-3 mt-12 text-[9px] uppercase tracking-[.24em] text-[#a88b7b]">Manage the night</p><nav className="grid gap-1">{adminLinks.map(([label, href, Icon]) => <Link key={href} href={href} onClick={() => setOpen(false)} className={`flex items-center gap-3 rounded-sm px-3 py-3 text-sm transition ${location === href ? 'bg-[#d69b45] font-bold text-[#34241f]' : 'text-[#dac7bb] hover:bg-white/5'}`} data-testid={`admin-nav-${label.toLowerCase().replace(' ', '-')}`}><Icon size={16} />{label}</Link>)}</nav><div className="absolute bottom-7 left-5 right-5 border-t border-white/10 pt-5"><Link href="/" className="flex items-center gap-2 text-xs text-[#a88b7b]" data-testid="link-view-site"><ExternalLink size={14} /> View live site</Link></div></aside>{open && <button className="fixed inset-0 z-30 bg-black/30 md:hidden" onClick={() => setOpen(false)} aria-label="Close navigation" data-testid="button-overlay" />}<div className="md:pl-64"><header className="flex h-20 items-center justify-between border-b border-[#d8c8b8] bg-[#f6f0e7] px-5 lg:px-10"><button onClick={() => setOpen(true)} className="md:hidden" data-testid="button-open-sidebar"><Menu /></button><div className="hidden text-xs text-[#8a7163] md:block">Jannat workspace <span className="mx-2">/</span> {adminLinks.find((l) => l[1] === location)?.[0] || 'Workspace'}</div><div className="ml-auto flex items-center gap-4"><span className="hidden text-xs text-[#8a7163] sm:inline">Toronto · 09:42</span><div className="grid h-9 w-9 place-items-center rounded-full bg-[#d69b45] text-xs font-bold">JE</div></div></header><main className="px-5 py-8 lg:px-10 lg:py-10">{children}</main></div></div>;
}
function AdminHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[#a45c3c]">{eyebrow}</p><h1 className="display-font mt-2 text-5xl leading-none text-[#34241f]">{title}</h1></div>{action}</div>; }
function AdminDashboard() {
  const q = useGetAdminOverview();
  const o = q.data;
  const stats = [{ label: 'Upcoming', value: o?.upcomingEvents ?? 0, Icon: CalendarDays }, { label: 'Past nights', value: o?.pastEvents ?? 0, Icon: Zap }, { label: 'Published albums', value: o?.publishedAlbums ?? 0, Icon: ImagePlus }, { label: 'Unread inquiries', value: o?.unreadMessages ?? 0, Icon: MessageCircle }];
  if (q.isLoading) return <AdminShell><Loading /></AdminShell>;
  return <AdminShell><AdminHeading eyebrow="Good evening, Jannat" title="The overview." action={<Link href="/admin/events/new" className="inline-flex items-center gap-2 rounded-full bg-[#4b231b] px-5 py-3 text-xs font-bold uppercase tracking-[.15em] text-[#f7eddf]" data-testid="link-create-event"><Plus size={15} /> New event</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(({ label, value, Icon }) => <div className="border border-[#d8c8b8] bg-[#f8f3eb] p-5" key={label}><div className="flex items-center justify-between"><span className="text-sm text-[#806b5f]">{label}</span><Icon size={17} className="text-[#a45c3c]" /></div><p className="mt-8 text-4xl font-bold">{value}</p><div className="mt-4 h-1 w-12 bg-[#d69b45]" /></div>)}</div><div className="mt-10 grid gap-6 lg:grid-cols-[1.4fr_.8fr]"><div className="border border-[#d8c8b8] bg-[#f8f3eb] p-6"><div className="flex items-center justify-between"><h2 className="display-font text-3xl">Recent events</h2><Link href="/admin/events" className="text-xs font-bold uppercase tracking-wider text-[#a45c3c]" data-testid="link-manage-events">Manage all</Link></div><div className="mt-6 divide-y divide-[#dfd2c5]">{o?.recentEvents?.length ? o.recentEvents.map((e) => <div className="flex items-center justify-between gap-4 py-4" key={e.id}><div className="flex items-center gap-3"><img src={img(e.poster)} alt="" className="h-12 w-12 object-cover" /><div><p className="font-bold">{e.title}</p><p className="text-xs text-[#806b5f]">{dateLabel(e.date)} · {e.city}</p></div></div><StatusBadge status={e.status} /></div>) : <Empty text="No recent events." />}</div></div><div className="flex flex-col justify-between bg-[#d69b45] p-7"><div><Sparkles size={21} /><h2 className="display-font mt-8 text-4xl leading-none">Keep the<br /><i>feeling current.</i></h2><p className="mt-4 max-w-xs text-sm leading-6 text-[#674329]">Update the homepage, add a new album, or tidy your media library without touching code.</p></div><Link href="/admin/homepage" className="mt-12 inline-flex items-center justify-between border-t border-[#8b5b2c] pt-4 text-xs font-bold uppercase tracking-wider" data-testid="link-edit-homepage">Edit homepage <ArrowUpRight size={15} /></Link></div></div></AdminShell>;
}
function StatusBadge({ status }: { status: string }) { return <span className={`rounded-full px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider ${status === 'UPCOMING' ? 'bg-[#dce8d8] text-[#35633e]' : status === 'DRAFT' ? 'bg-[#eee0c7] text-[#895f2d]' : 'bg-[#e6d7d0] text-[#8a4c3c]'}`}>{status.toLowerCase()}</span>; }
function AdminEvents() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState<any>(undefined); const q = useListAdminEvents({ search: search || undefined, status }); const qc = useQueryClient(); const del = useDeleteEvent(); const dup = useDuplicateEvent();
  const remove = (id: number) => { if (window.confirm('Delete this event?')) del.mutate({ id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListAdminEventsQueryKey() }) }); };
  return <AdminShell><AdminHeading eyebrow="Content / Events" title="Your nights." action={<Link href="/admin/events/new" className="inline-flex items-center gap-2 rounded-full bg-[#4b231b] px-5 py-3 text-xs font-bold uppercase tracking-[.15em] text-[#f7eddf]" data-testid="link-new-event"><Plus size={15} /> Add event</Link>} /><div className="mb-5 flex flex-wrap gap-3"><div className="relative flex-1 sm:max-w-xs"><Search className="absolute left-3 top-3 text-[#8a7163]" size={15} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search events" className="focus-ring h-10 w-full border border-[#d8c8b8] bg-[#f8f3eb] pl-9 pr-3 text-sm" data-testid="input-search-events" /></div><select value={status || ''} onChange={(e) => setStatus(e.target.value || undefined)} className="focus-ring h-10 border border-[#d8c8b8] bg-[#f8f3eb] px-3 text-sm" data-testid="select-event-status"><option value="">Every status</option><option value="UPCOMING">Upcoming</option><option value="PAST">Past</option><option value="DRAFT">Draft</option></select></div><div className="overflow-x-auto border border-[#d8c8b8] bg-[#f8f3eb]">{q.isLoading ? <Loading /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : q.data?.length ? <table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b border-[#d8c8b8] text-[10px] uppercase tracking-wider text-[#8a7163]"><tr><th className="px-5 py-4">Event</th><th>Date</th><th>City</th><th>Status</th><th className="px-5 py-4 text-right">Actions</th></tr></thead><tbody className="divide-y divide-[#e6dbcf]">{q.data.map((e) => <tr key={e.id} data-testid={`row-event-${e.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><img src={img(e.poster)} alt="" className="h-10 w-10 object-cover" /><div><p className="font-bold">{e.title}</p><p className="text-xs text-[#8a7163]">{e.venue}</p></div></div></td><td>{dateLabel(e.date)}</td><td>{e.city}</td><td><StatusBadge status={e.status} /></td><td className="px-5 py-4"><div className="flex justify-end gap-1"><Link href={`/admin/events/${e.id}/edit`} className="rounded p-2 hover:bg-[#eadfd2]" data-testid={`link-edit-event-${e.id}`}><Pencil size={15} /></Link><button onClick={() => dup.mutate({ id: e.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListAdminEventsQueryKey() }) })} className="rounded p-2 hover:bg-[#eadfd2]" title="Duplicate" data-testid={`button-duplicate-event-${e.id}`}><ChevronRight size={15} /></button><button onClick={() => remove(e.id)} className="rounded p-2 text-[#9f4939] hover:bg-[#f1d9d3]" data-testid={`button-delete-event-${e.id}`}><Trash2 size={15} /></button></div></td></tr>)}</tbody></table> : <div className="p-6"><Empty text="No events match this search." /></div>}</div></AdminShell>;
}

